         */sumSquares: Double, 
        /**
         * Largest absolute amplitude seen.
         */peak: Double) {
        self.sampleCount = sampleCount
        self.nonSilentCount = nonSilentCount
        self.sumSquares = sumSquares
        self.peak = peak
    }
}



